sys_script_include.script:
function GetInstrumentDetailsUrl(strSysId)
{
	var GetStringValue = x_snc_devtools.GetStringValue;

	var grInstrument = GetInstrumentRecord(strSysId);
	if (grInstrument == false)
	{
		return '';
	}
	var strType = GetStringValue(grInstrument.type);
	if (strType == 'stock')
	{
		return 'https://www.onvista.de/aktien/'+grInstrument.isin;		
	}
	if (strType == 'etf')
	{
		return 'https://www.onvista.de/etf/'+grInstrument.isin;		
	}
	if (strType == 'bond')
	{
		return 'https://www.onvista.de/anleihen/'+grInstrument.isin;		
	}
	if (strType == 'fund')
	{
		return 'https://www.onvista.de/fonds/'+grInstrument.isin;		
	}
	return 'https://www.onvista.de/';
}
